import { test, expect } from '@playwright/test';

test.describe('JavaScript Confirm Dialog', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/javascript_alerts');
  });

  test('should handle JS confirm dialog and record user choice', async ({ page }) => {
    // Click the button to open the confirm dialog
    const confirmButton = page.getByRole('button', { name: /click for js confirm/i });
    await confirmButton.click();

    // Accept the confirm dialog
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await confirmDialog.getByRole('button', { name: /ok/i }).click();

    // Verify the result element shows 'You clicked: Ok'
    const resultElement = page.locator('#result');
    await expect(resultElement).toContainText('You clicked: Ok');

    // Verify the confirmation dialog is closed
    await expect(confirmDialog).not.toBeVisible();
  });

  test('should handle JS confirm dialog and record user choice when dismissing', async ({ page }) => {
    // Click the button to open the confirm dialog
    const confirmButton = page.getByRole('button', { name: /click for js confirm/i });
    await confirmButton.click();

    // Dismiss the confirm dialog
    const confirmDialog = page.locator('[data-testid="confirm-dialog"]');
    await confirmDialog.getByRole('button', { name: /cancel/i }).click();

    // Verify the result element shows 'You clicked Cancel'
    const resultElement = page.locator('#result');
    await expect(resultElement).toContainText('You clicked Cancel');

    // Verify the confirmation dialog is closed
    await expect(confirmDialog).not.toBeVisible();
  });
});
